import json, os

OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "d1.json")


def expl(correct, why, wrong, tips):
    if len(correct) == 1:
        head = f"### ✅ Why Option {correct[0]} is Correct"
    else:
        head = "### ✅ Why Options " + " & ".join(correct) + " are Correct"
    s = head + "\n\n" + "\n".join(f"* **{k}:** {v}" for k, v in why) + "\n\n---\n\n"
    s += "### ❌ Why Other Options Are Incorrect\n\n"
    s += "\n".join(f"* **Option {k} is incorrect:** {v}" for k, v in sorted(wrong.items())) + "\n\n---\n\n"
    s += "### 💡 SAA-C03 Exam Concept & AWS Best Practice\n\n"
    s += "\n".join(f"{i}. **{k}:** {v}" for i, (k, v) in enumerate(tips, 1))
    return s


def q(task, topics, prompt, options, correct, why, wrong, tips):
    multi = len(correct) > 1
    assert set(wrong) | set(correct) == set(options), prompt[:40]
    assert not (set(wrong) & set(correct))
    if multi:
        n = len(correct)
        assert len(options) == (5 if n == 2 else 6)
        assert prompt.endswith("(Select TWO.)" if n == 2 else "(Select THREE.)")
    else:
        assert len(options) == 4
    return {
        "domain": 1,
        "task": task,
        "topics": topics,
        "prompt": prompt,
        "options": options,
        "isMulti": multi,
        "requiredCount": len(correct),
        "correctAnswers": correct,
        "explanation": expl(correct, why, wrong, tips),
    }


