set1.append(q("1.1", ["IAM", "Permissions boundaries"],
 "A platform team wants developers to create IAM roles for their own Lambda functions without waiting for the central security team. The security team must make sure that any role a developer creates can never have more permissions than an approved set of actions, even if the developer attaches AdministratorAccess to it. Which solution meets these requirements?",
 {"A": "Attach a service control policy (SCP) to the developers' account that denies iam:CreateRole, iam:AttachRolePolicy, and iam:PutRolePolicy for all principals except the security team's role.",
  "B": "Require developers to submit a ticket so that the security team can create every Lambda execution role on their behalf.",
  "C": "Define the approved actions in a managed policy, and allow iam:CreateRole only when the iam:PermissionsBoundary condition key equals that policy's ARN.",
  "D": "Attach the AWS managed PowerUserAccess policy to the developers so that they cannot modify IAM users."},
 ["C"],
 [("Permissions boundary", "A permissions boundary sets the maximum permissions that an identity-based policy can grant to a role. Effective permissions are the intersection of the two, so attaching AdministratorAccess cannot exceed the boundary."),
  ("Delegated, safe self-service", "Conditioning iam:CreateRole (and iam:PutRolePermissionsBoundary) on the iam:PermissionsBoundary key forces every new role to carry the boundary. You should also deny deleting or changing the boundary."),
  ("No bottleneck", "Developers can still create roles themselves, which meets the self-service requirement.")],
 {"A": "Denying role creation blocks the self-service requirement entirely.",
  "B": "A ticket-based process is the bottleneck that the company wants to remove.",
  "D": "PowerUserAccess denies most IAM actions, including iam:CreateRole, so developers could not create roles at all."},
 [("'Delegate IAM administration safely'", "This points to permissions boundaries."),
  ("Policy evaluation", "Effective permissions = identity policy ∩ permissions boundary ∩ SCP/RCP (∩ session policy). An explicit deny anywhere wins."),
  ("Exam tip", "SCPs limit whole accounts. Permissions boundaries limit individual users or roles.")]))

